import { attachWebglRenderer, loadTerminalAssets } from "./terminalRenderer";
import {
  getWebglLifecycleCounters,
  resetWebglLifecycleCountersForTests,
} from "./terminalRendererMetrics";

describe("terminal renderer runtime", () => {
  beforeEach(() => {
    mocks.webglDispose.mockClear();
    mocks.clearContextLoss();
    resetWebglLifecycleCountersForTests();
  });

  it("keeps xterm, fit, CSS, and WebGL out of the eager module path", async () => {
    expect(mocks.loadCounts()).toEqual({ xtermLoads: 0, fitLoads: 0, cssLoads: 0, webglLoads: 0 });

    const assets = await loadTerminalAssets();

    expect(assets.Terminal).toBe(mocks.MockTerminal);
    expect(assets.FitAddon).toBe(mocks.MockFitAddon);
    expect(mocks.loadCounts()).toEqual({ xtermLoads: 1, fitLoads: 1, cssLoads: 1, webglLoads: 0 });
  });

  it("disposes WebGL exactly once on context loss and exposes Canvas fallback counters", async () => {
    const terminal = { loadAddon: vi.fn() } as unknown as Terminal;
    const dispose = await attachWebglRenderer(terminal);

    expect(getWebglLifecycleCounters()).toEqual({
      created: 1,
      active: 1,
      disposed: 0,
      contextLosses: 0,
      loadFailures: 0,
      canvasFallbacks: 0,
    });
    expect(globalThis.__ORCA_WEBGL_LIFECYCLE__).toEqual(getWebglLifecycleCounters());

    mocks.triggerContextLoss();

    expect(mocks.webglDispose).toHaveBeenCalledTimes(1);
    expect(getWebglLifecycleCounters()).toEqual({
      created: 1,
      active: 0,
      disposed: 1,
      contextLosses: 1,
      loadFailures: 0,
      canvasFallbacks: 1,
    });

    dispose();
    expect(mocks.webglDispose).toHaveBeenCalledTimes(1);
  });

  it("falls back to Canvas and balances counters when WebGL attachment fails", async () => {
    const terminal = {
      loadAddon: vi.fn(() => {
        throw new Error("WebGL unavailable");
      }),
    } as unknown as Terminal;

    const dispose = await attachWebglRenderer(terminal);

    expect(mocks.webglDispose).toHaveBeenCalledTimes(1);
    expect(getWebglLifecycleCounters()).toEqual({
      created: 1,
      active: 0,
      disposed: 1,
      contextLosses: 0,
      loadFailures: 1,
      canvasFallbacks: 1,
    });
    expect(() => dispose()).not.toThrow();
  });
});

import type { LayoutState, Pane, TerminalSession } from "../lib/types";
import { TerminalPane } from "./TerminalPane";

type TerminalSplitViewProps = {
  layout: LayoutState;
  sessions: Record<string, TerminalSession>;
};

export function TerminalSplitView({ layout, sessions }: TerminalSplitViewProps) {
  const primaryTab = layout.tabs.find((tab) => tab.id === layout.primaryTabId) ?? null;
  const secondaryTab = layout.split !== "none"
    ? layout.tabs.find((tab) => tab.id === layout.secondaryTabId) ?? null
    : null;
  const primarySession = primaryTab ? sessions[primaryTab.sessionId] ?? null : null;
  const secondarySession = secondaryTab ? sessions[secondaryTab.sessionId] ?? null : null;
  const primaryPane: Pane | null = primaryTab ? { id: "primary", tabId: primaryTab.id } : null;
  const secondaryPane: Pane | null = secondaryTab ? { id: "secondary", tabId: secondaryTab.id } : null;

  if (!primaryTab || !primaryPane || !primarySession) {
    return <div className="relative flex-1 overflow-hidden bg-terminal" data-testid="terminal-layout" data-split="none" />;
  }

  return (
    <div
      className={`relative flex flex-1 overflow-hidden ${
        layout.split === "horizontal" ? "flex-row" : layout.split === "vertical" ? "flex-col" : ""
      }`}
      data-testid="terminal-layout"
      data-split={layout.split}
    >
      <div className="relative h-full w-full flex-1 overflow-hidden" data-testid="primary-pane" data-pane-id={primaryPane.id}>
        <TerminalPane key={primaryTab.id} session={primarySession} active />
      </div>

      {layout.split !== "none" && secondaryTab && secondaryPane && secondarySession ? (
        <div
          className={`relative h-full w-full flex-1 overflow-hidden ${
            layout.split === "horizontal" ? "border-l border-border" : "border-t border-border"
          }`}
          data-testid="secondary-pane"
          data-pane-id={secondaryPane.id}
        >
          <TerminalPane key={secondaryTab.id} session={secondarySession} active />
        </div>
      ) : null}
    </div>
  );
}

import type { LayoutState, SplitMode, TerminalTab } from "../lib/types";

export type LayoutAction =
  | { type: "ADD_TAB"; tab: TerminalTab; activate?: boolean }
  | { type: "CLOSE_TAB"; tabId: string; replacementTab?: TerminalTab }
  | { type: "ACTIVATE_PRIMARY"; tabId: string }
  | { type: "ACTIVATE_SECONDARY"; tabId: string }
  | {
      type: "ENABLE_SPLIT";
      orientation: Exclude<SplitMode, "none">;
      secondaryTabId?: string;
      secondaryTab?: TerminalTab;
    }
  | { type: "ROTATE_SPLIT" }
  | { type: "DISABLE_SPLIT" };

export function createLayoutState(tabs: TerminalTab[] = [], primaryTabId?: string | null): LayoutState {
  return normalizeLayout({
    tabs,
    primaryTabId: primaryTabId ?? tabs[0]?.id ?? null,
    secondaryTabId: null,
    split: "none",
  });
}

export function layoutReducer(state: LayoutState, action: LayoutAction): LayoutState {
  switch (action.type) {
    case "ADD_TAB": {
      const tabs = state.tabs.some((tab) => tab.id === action.tab.id) ? state.tabs : [...state.tabs, action.tab];
      return normalizeLayout({
        ...state,
        tabs,
        primaryTabId: action.activate === false ? state.primaryTabId : action.tab.id,
      });
    }
    case "CLOSE_TAB": {
      if (!state.tabs.some((tab) => tab.id === action.tabId)) return normalizeLayout(state);

      let tabs = state.tabs.filter((tab) => tab.id !== action.tabId);
      if (tabs.length === 0 && action.replacementTab) tabs = [action.replacementTab];

      let primaryTabId = state.primaryTabId === action.tabId ? tabs[0]?.id ?? null : state.primaryTabId;
      if (primaryTabId && !tabs.some((tab) => tab.id === primaryTabId)) primaryTabId = tabs[0]?.id ?? null;

      let secondaryTabId = state.secondaryTabId === action.tabId ? null : state.secondaryTabId;
      if (secondaryTabId && !tabs.some((tab) => tab.id === secondaryTabId)) secondaryTabId = null;

      let split = state.split;
      if (split !== "none") {
        if (!secondaryTabId || secondaryTabId === primaryTabId) {
          secondaryTabId = tabs.find((tab) => tab.id !== primaryTabId)?.id ?? null;
        }
        if (!secondaryTabId) split = "none";
      }

      return normalizeLayout({ tabs, primaryTabId, secondaryTabId, split });
    }
    case "ACTIVATE_PRIMARY": {
      if (!state.tabs.some((tab) => tab.id === action.tabId)) return state;
      return normalizeLayout({ ...state, primaryTabId: action.tabId });
    }
    case "ACTIVATE_SECONDARY": {
      if (state.split === "none" || !state.tabs.some((tab) => tab.id === action.tabId)) return state;
      return normalizeLayout({ ...state, secondaryTabId: action.tabId });
    }
    case "ENABLE_SPLIT": {
      const tabs = action.secondaryTab && !state.tabs.some((tab) => tab.id === action.secondaryTab?.id)
        ? [...state.tabs, action.secondaryTab]
        : state.tabs;
      const primaryTabId = state.primaryTabId ?? tabs[0]?.id ?? null;
      const requestedSecondaryId = action.secondaryTab?.id ?? action.secondaryTabId ?? null;
      const secondaryTabId =
        requestedSecondaryId && requestedSecondaryId !== primaryTabId && tabs.some((tab) => tab.id === requestedSecondaryId)
          ? requestedSecondaryId
          : tabs.find((tab) => tab.id !== primaryTabId)?.id ?? null;

      return normalizeLayout({
        tabs,
        primaryTabId,
        secondaryTabId,
        split: secondaryTabId ? action.orientation : "none",
      });
    }
    case "ROTATE_SPLIT":
      return normalizeLayout({
        ...state,
        split: state.split === "horizontal" ? "vertical" : state.split === "vertical" ? "horizontal" : "none",
      });
    case "DISABLE_SPLIT":
      return normalizeLayout({ ...state, split: "none", secondaryTabId: null });
  }
}

function normalizeLayout(state: LayoutState): LayoutState {
  const tabs = dedupeTabs(state.tabs);
  if (tabs.length === 0) {
    return { tabs: [], primaryTabId: null, secondaryTabId: null, split: "none" };
  }

  const primaryTabId = tabs.some((tab) => tab.id === state.primaryTabId) ? state.primaryTabId : tabs[0].id;
  let split = state.split;
  let secondaryTabId = tabs.some((tab) => tab.id === state.secondaryTabId) ? state.secondaryTabId : null;

  if (secondaryTabId === primaryTabId) {
    secondaryTabId = tabs.find((tab) => tab.id !== primaryTabId)?.id ?? null;
  }

  if (split !== "none" && !secondaryTabId) {
    secondaryTabId = tabs.find((tab) => tab.id !== primaryTabId)?.id ?? null;
  }

  if (split !== "none" && !secondaryTabId) split = "none";
  if (split === "none") secondaryTabId = null;

  return { tabs, primaryTabId, secondaryTabId, split };
}

function dedupeTabs(tabs: TerminalTab[]) {
  const seen = new Set<string>();
  return tabs.filter((tab) => {
    if (seen.has(tab.id)) return false;
    seen.add(tab.id);
    return true;
  });
}

